ton" disabled style="width:100%;border:1px solid #b9a9ce;background:#eee7f4;color:#4a315e;padding:13px;font-weight:800;cursor:not-allowed">Shop Pay · planned</button><p class="sn-note">Shop Pay Wallet can be connected after Sawyer’s Shopify merchant setup and payment approval. This preview does not take payment.</p></div>@if(!$shippingEnabled || !$checkoutReady)<p class="sn-alert" role="status">Checkout setup is in progress. Your bag is ready to explore, and shipping and payment will open after merchant account checks are complete.</p>@elseif(($missingShippingWeights ?? collect())->isNotEmpty())<p class="sn-alert" role="status">Remove the items unavailable for shipping to continue.</p>@elseif(!($checkoutAttempt ?? null))<form method="POST" action="{{ route('managed-website.store.checkout') }}" id="sn-checkout">@csrf<input type="hidden" name="fulfillment_method" value="ship"><label class="sn-label" for="customer-name">Full name</label><input required class="sn-input" id="customer-name" name="name" autocomplete="name"><label class="sn-label" for="customer-email">Email</label><input required class="sn-input" id="customer-email" name="email" type="email" autocomplete="email"><label class="sn-label" for="customer-phone">Phone (optional)</label><input class="sn-input" id="customer-phone" name="phone" autocomplete="tel">@include('managed-website.shipping-fields')<button class="sn-btn" type="submit" disabled style="margin-top:18px">Continue to secure payment</button></form>@endif</aside>@endif</div>
